public record Standing(String merchant, long approvals, long rank) {}

public List<Standing> top(int n) {
    List<Tuple> rows = redis.zrangeWithScores(key, ZRangeParams.zrangeParams(0, n - 1).rev());
    List<Standing> out = new ArrayList<>(rows.size());
    for (int i = 0; i < rows.size(); i++) {
        Tuple t = rows.get(i);
        out.add(new Standing(t.getElement(), (long) t.getScore(), i + 1));   // ranks start at 1 for people
    }
    return out;
}

